  c: '#include <stddef.h>\n#include <stdint.h>\ntypedef struct{int32_t*data;size_t len;}IntArray;typedef struct{unsigned char*data;size_t len;}ByteString;typedef struct{ByteString*data;size_t len;}StringArray;void reverseString(StringArray a){for(size_t i=0;i<a.len/2;i++){ByteString t=a.data[i];a.data[i]=a.data[a.len-1-i];a.data[a.len-1-i]=t;}}void merge(IntArray a,int32_t m,IntArray b,int32_t n){int i=m-1,j=n-1,k=m+n-1;while(j>=0)a.data[k--]=i>=0&&a.data[i]>b.data[j]?a.data[i--]:b.data[j--];}void rotateArray(IntArray a,int32_t k){if(!a.len)return;k%=a.len;while(k--){int32_t x=a.data[a.len-1];for(size_t i=a.len-1;i;i--)a.data[i]=a.data[i-1];a.data[0]=x;}}',
  cpp: '#include <vector>\n#include <string>\n#include <algorithm>\nvoid reverseString(std::vector<std::string>&a){std::reverse(a.begin(),a.end());}void merge(std::vector<int>&a,int m,std::vector<int>b,int n){a.resize(m);a.insert(a.end(),b.begin(),b.begin()+n);std::sort(a.begin(),a.end());}void rotateArray(std::vector<int>&a,int k){if(a.empty())return;k%=a.size();std::rotate(a.begin(),a.end()-k,a.end());}',
  csharp: 'public class Solution{public void reverseString(string[]a){System.Array.Reverse(a);}public void merge(int[]a,int m,int[]b,int n){int i=m-1,j=n-1,k=m+n-1;while(j>=0)a[k--]=i>=0&&a[i]>b[j]?a[i--]:b[j--];}public void rotateArray(int[]a,int k){if(a.Length==0)return;k%=a.Length;var b=(int[])a.Clone();for(int i=0;i<a.Length;i++)a[(i+k)%a.Length]=b[i];}}',
