  csharp: 'public class Solution{int R(int[]p,int x){return p[x]==x?x:(p[x]=R(p,p[x]));}long M(int n,int[][]e,int skip=-1,int take=-1){int[]p=new int[n];for(int i=0;i<n;i++)p[i]=i;var o=new System.Collections.Generic.List<int>();for(int i=0;i<e.Length;i++)o.Add(i);o.Sort((a,b)=>e[a][2]-e[b][2]);long w=0;int c=0;if(take>=0){p[R(p,e[take][0])]=R(p,e[take][1]);w+=e[take][2];c++;}foreach(int i in o)if(i!=skip&&i!=take){int a=R(p,e[i][0]),b=R(p,e[i][1]);if(a!=b){p[a]=b;w+=e[i][2];c++;}}return c==n-1?w:long.MaxValue;}public int[][]findCriticalAndPseudoCriticalEdges(int n,int[][]e){long b=M(n,e);var x=new System.Collections.Generic.List<int>();var y=new System.Collections.Generic.List<int>();for(int i=0;i<e.Length;i++)if(M(n,e,i)>b)x.Add(i);else if(M(n,e,-1,i)==b)y.Add(i);return new[]{x.ToArray(),y.ToArray()};}int[]T(int k,int[][]q){var g=new System.Collections.Generic.List<int>[k];int[]d=new int[k];for(int i=0;i<k;i++)g[i]=new System.Collections.Generic.List<int>();foreach(var z in q){g[z[0]-1].Add(z[1]-1);d[z[1]-1]++;}var s=new System.Collections.Generic.Stack<int>();var o=new System.Collections.Generic.List<int>();for(int i=0;i<k;i++)if(d[i]==0)s.Push(i);while(s.Count>0){int x=s.Pop();o.Add(x+1);foreach(int y in g[x])if(--d[y]==0)s.Push(y);}return o.Count==k?o.ToArray():new int[0];}public int[][]buildMatrix(int k,int[][]r,int[][]c){var a=T(k,r);var b=T(k,c);if(a.Length==0||b.Length==0)return new int[0][];int[]rp=new int[k+1],cp=new int[k+1];for(int i=0;i<k;i++){rp[a[i]]=i;cp[b[i]]=i;}var m=new int[k][];for(int i=0;i<k;i++)m[i]=new int[k];for(int x=1;x<=k;x++)m[rp[x]][cp[x]]=x;return m;}}',
  php: '<?php function findCriticalAndPseudoCriticalEdges(int $n,array $e):array{$mst=function($skip=-1,$take=-1)use($n,$e){$p=range(0,$n-1);$f=function($x)use(&$f,&$p){return$p[$x]===$x?$x:($p[$x]=$f($p[$x]));};$o=array_keys($e);usort($o,fn($a,$b)=>$e[$a][2]<=>$e[$b][2]);if($take>=0)array_unshift($o,$take);$w=$c=0;foreach($o as$i)if($i!==$skip&&($i!==$take||$c===0)){[$a,$b,$z]=$e[$i];$a=$f($a);$b=$f($b);if($a!==$b){$p[$a]=$b;$w+=$z;$c++;}}return$c===$n-1?$w:PHP_INT_MAX;};$b=$mst();$x=$y=[];foreach($e as$i=>$_)if($mst($i)>$b)$x[]=$i;elseif($mst(-1,$i)===$b)$y[]=$i;return[$x,$y];}function buildMatrix(int $k,array $r,array $c):array{$top=function($q)use($k){$g=array_fill(0,$k,[]);$d=array_fill(0,$k,0);foreach($q as[$a,$b]){$g[$a-1][]=$b-1;$d[$b-1]++;}$s=[];$o=[];foreach($d as$i=>$v)if(!$v)$s[]=$i;while($s){$x=array_pop($s);$o[]=$x+1;foreach($g[$x]as$y)if(!--$d[$y])$s[]=$y;}return count($o)===$k?$o:[];};$a=$top($r);$b=$top($c);if(!$a||!$b)return[];$rp=$cp=[];foreach($a as$i=>$x)$rp[$x]=$i;foreach($b as$i=>$x)$cp[$x]=$i;$m=array_fill(0,$k,array_fill(0,$k,0));for($x=1;$x<=$k;$x++)$m[$rp[$x]][$cp[$x]]=$x;return$m;}',
