    python: 'def calcEquation(e,v,q):\n g={}\n for (a,b),w in zip(e,v):g.setdefault(a,[]).append((b,w));g.setdefault(b,[]).append((a,1/w))\n def f(a,b,s):\n  if a not in g:return -1\n  if a==b:return 1\n  s.add(a)\n  for x,w in g[a]:\n   if x not in s:\n    z=f(x,b,s)\n    if z>=0:return w*z\n  return -1\n return [f(a,b,set()) for a,b in q]',
    java: 'public class Solution{public double[] calcEquation(String[][]e,double[]v,String[][]q){var g=new java.util.HashMap<String,java.util.List<Object[]>>();for(int i=0;i<e.length;i++){g.computeIfAbsent(e[i][0],x->new java.util.ArrayList<>()).add(new Object[]{e[i][1],v[i]});g.computeIfAbsent(e[i][1],x->new java.util.ArrayList<>()).add(new Object[]{e[i][0],1/v[i]});}double[]r=new double[q.length];for(int i=0;i<q.length;i++)r[i]=f(q[i][0],q[i][1],g,new java.util.HashSet<>());return r;}double f(String a,String b,java.util.Map<String,java.util.List<Object[]>>g,java.util.Set<String>s){if(!g.containsKey(a))return-1;if(a.equals(b))return 1;s.add(a);for(Object[]x:g.get(a))if(!s.contains(x[0])){double z=f((String)x[0],b,g,s);if(z>=0)return(double)x[1]*z;}return-1;}}',
    javascript: 'function calcEquation(e,v,q){const g=new Map;for(let i=0;i<e.length;i++){const[a,b]=e[i];if(!g.has(a))g.set(a,[]);if(!g.has(b))g.set(b,[]);g.get(a).push([b,v[i]]);g.get(b).push([a,1/v[i]])}const f=(a,b,s)=>{if(!g.has(a))return-1;if(a===b)return 1;s.add(a);for(const[x,w]of g.get(a))if(!s.has(x)){const z=f(x,b,s);if(z>=0)return w*z}return-1};return q.map(([a,b])=>f(a,b,new Set))}',
    typescript: 'function calcEquation(e:string[][],v:number[],q:string[][]):number[]{const g=new Map<string,[string,number][]>;for(let i=0;i<e.length;i++){const[a,b]=e[i];if(!g.has(a))g.set(a,[]);if(!g.has(b))g.set(b,[]);g.get(a)!.push([b,v[i]]);g.get(b)!.push([a,1/v[i]])}const f=(a:string,b:string,s:Set<string>):number=>{if(!g.has(a))return-1;if(a===b)return 1;s.add(a);for(const[x,w]of g.get(a)!)if(!s.has(x)){const z=f(x,b,s);if(z>=0)return w*z}return-1};return q.map(([a,b])=>f(a,b,new Set<string>()))}',
    c: '#include <stddef.h>\n#include <stdlib.h>\n#include <string.h>\ntypedef struct{unsigned char*data;size_t len;}ByteString;typedef struct{ByteString*data;size_t len;}StringArray;typedef struct{StringArray*data;size_t len;}StringMatrix;typedef struct{double*data;size_t len;}Numbers;static int eq(ByteString a,ByteString b){return a.len==b.len&&!memcmp(a.data,b.data,a.len);}static double dfs(int a,int b,int n,double w[64][64],int*s){if(a==b)return 1;s[a]=1;for(int i=0;i<n;i++)if(!s[i]&&w[a][i]){double z=dfs(i,b,n,w,s);if(z>=0)return w[a][i]*z;}return-1;}Numbers calcEquation(StringMatrix e,Numbers v,StringMatrix q){ByteString names[64];int n=0;double w[64][64]={{0}};for(size_t i=0;i<e.len;i++){int z[2];for(int k=0;k<2;k++){z[k]=-1;for(int j=0;j<n;j++)if(eq(names[j],e.data[i].data[k]))z[k]=j;if(z[k]<0){z[k]=n;names[n++]=e.data[i].data[k];}}w[z[0]][z[1]]=v.data[i];w[z[1]][z[0]]=1/v.data[i];}Numbers r={malloc(q.len*sizeof(double)),q.len};for(size_t i=0;i<q.len;i++){int z[2];for(int k=0;k<2;k++){z[k]=-1;for(int j=0;j<n;j++)if(eq(names[j],q.data[i].data[k]))z[k]=j;}int s[64]={0};r.data[i]=(z[0]<0||z[1]<0)?-1:dfs(z[0],z[1],n,w,s);}return r;}',
    cpp: '#include <vector>\n#include <string>\n#include <unordered_map>\n#include <unordered_set>\nstd::vector<double> calcEquation(std::vector<std::vector<std::string>>e,std::vector<double>v,std::vector<std::vector<std::string>>q){std::unordered_map<std::string,std::vector<std::pair<std::string,double>>>g;for(int i=0;i<(int)e.size();i++){g[e[i][0]].push_back({e[i][1],v[i]});g[e[i][1]].push_back({e[i][0],1/v[i]});}auto f=[&](auto&&f,std::string a,std::string b,std::unordered_set<std::string>&s)->double{if(!g.count(a))return-1;if(a==b)return 1;s.insert(a);for(auto[x,w]:g[a])if(!s.count(x)){double z=f(f,x,b,s);if(z>=0)return w*z;}return-1;};std::vector<double>r;for(auto&x:q){std::unordered_set<std::string>s;r.push_back(f(f,x[0],x[1],s));}return r;}',
    csharp: 'public class Solution{public double[] calcEquation(string[][]e,double[]v,string[][]q){var g=new System.Collections.Generic.Dictionary<string,System.Collections.Generic.List<System.Tuple<string,double>>>();for(int i=0;i<e.Length;i++){if(!g.ContainsKey(e[i][0]))g[e[i][0]]=new System.Collections.Generic.List<System.Tuple<string,double>>();if(!g.ContainsKey(e[i][1]))g[e[i][1]]=new System.Collections.Generic.List<System.Tuple<string,double>>();g[e[i][0]].Add(System.Tuple.Create(e[i][1],v[i]));g[e[i][1]].Add(System.Tuple.Create(e[i][0],1/v[i]));}var r=new double[q.Length];for(int i=0;i<q.Length;i++)r[i]=F(q[i][0],q[i][1],g,new System.Collections.Generic.HashSet<string>());return r;}double F(string a,string b,System.Collections.Generic.Dictionary<string,System.Collections.Generic.List<System.Tuple<string,double>>>g,System.Collections.Generic.HashSet<string>s){if(!g.ContainsKey(a))return-1;if(a==b)return 1;s.Add(a);foreach(var x in g[a])if(!s.Contains(x.Item1)){double z=F(x.Item1,b,g,s);if(z>=0)return x.Item2*z;}return-1;}}',
    php: '<?php function calcEquation(array $e,array $v,array $q):array{$g=[];foreach($e as$i=>[$a,$b]){$g[$a][]=[$b,$v[$i]];$g[$b][]=[$a,1/$v[$i]];}$f=function($a,$b,$s)use(&$f,$g){if(!isset($g[$a]))return-1;if($a===$b)return 1;$s[$a]=1;foreach($g[$a]as[$x,$w])if(!isset($s[$x])){$z=$f($x,$b,$s);if($z>=0)return$w*$z;}return-1;};return array_map(fn($x)=>$f($x[0],$x[1],[]),$q);}',
    r: 'calcEquation<-function(e,v,q){names<-unique(unlist(e));n<-length(names);w<-matrix(0,n,n);for(i in seq_along(e)){a<-match(e[[i]][1],names);b<-match(e[[i]][2],names);w[a,b]<-v[i];w[b,a]<-1/v[i]};f<-function(a,b,s){if(is.na(a)||is.na(b))return(-1);if(a==b)return(1);s[a]<-TRUE;for(x in which(w[a,]!=0))if(!s[x]){z<-f(x,b,s);if(z>=0)return(w[a,x]*z)};-1};vapply(q,function(x)f(match(x[1],names),match(x[2],names),rep(FALSE,n)),numeric(1))}',
