    csharp: 'public class Solution{public int[][] fourSum(int[]a,int t){var r=new System.Collections.Generic.Dictionary<string,int[]>();for(int i=0;i<a.Length;i++)for(int j=i+1;j<a.Length;j++)for(int k=j+1;k<a.Length;k++)for(int l=k+1;l<a.Length;l++)if((long)a[i]+a[j]+a[k]+a[l]==t){var x=new[]{a[i],a[j],a[k],a[l]};System.Array.Sort(x);r[string.Join(",",x)]=x;}var z=new int[r.Count][];r.Values.CopyTo(z,0);return z;}}',
