    c: '#include <stdint.h>\n#include <stdlib.h>\ntypedef struct LFUCache{int c,t;int used[256],v[256],f[256],at[256];}LFUCache;LFUCache*lFUCacheCreate(int32_t c){LFUCache*s=calloc(1,sizeof(*s));s->c=c;return s;}int32_t lFUCacheGet(LFUCache*s,int32_t k){if(k<0||k>=256||!s->used[k])return-1;s->f[k]++;s->at[k]=++s->t;return s->v[k];}void lFUCachePut(LFUCache*s,int32_t k,int32_t v){if(!s->c)return;if(s->used[k]){s->v[k]=v;lFUCacheGet(s,k);return;}int n=0;for(int i=0;i<256;i++)n+=s->used[i];if(n==s->c){int z=-1;for(int i=0;i<256;i++)if(s->used[i]&&(z<0||s->f[i]<s->f[z]||s->f[i]==s->f[z]&&s->at[i]<s->at[z]))z=i;s->used[z]=0;}s->used[k]=1;s->v[k]=v;s->f[k]=1;s->at[k]=++s->t;}',
