    csharp: 'public class LFUCache{int c,t;class X{public int v,f,at;}System.Collections.Generic.Dictionary<int,X>m=new System.Collections.Generic.Dictionary<int,X>();public LFUCache(int c){this.c=c;}public int get(int k){if(!m.ContainsKey(k))return-1;var x=m[k];x.f++;x.at=++t;return x.v;}public void put(int k,int v){if(c==0)return;if(m.ContainsKey(k)){m[k].v=v;get(k);return;}if(m.Count==c){int z=0;bool first=true;foreach(var q in m)if(first||q.Value.f<m[z].f||q.Value.f==m[z].f&&q.Value.at<m[z].at){z=q.Key;first=false;}m.Remove(z);}m[k]=new X{v=v,f=1,at=++t};}}',
